old_editor = '''const openContentEditor = ({ title, description, fields }) => new Promise((resolve) => {\n  const overlay = document.createElement("div"); overlay.className = "content-editor-overlay";\n  const dialog = document.createElement("form"); dialog.className = "content-editor-dialog";\n  dialog.innerHTML = `<div class="content-editor-header"><div><span class="eyebrow">BEARBEITEN</span><h2>${title}</h2><p>${description || "Änderungen prüfen und anschließend speichern."}</p></div><button type="button" class="content-editor-close" aria-label="Schließen">×</button></div>`;\n  fields.forEach((definition) => {\n    const label = document.createElement("label"); label.className = "content-editor-field"; label.textContent = definition.label;\n    const element = definition.type === "textarea" ? document.createElement("textarea") : document.createElement("input");\n    element.name = definition.name; element.type = definition.type === "file" ? "file" : definition.type || "text";\n    if (definition.type === "file") element.accept = "image/png,image/jpeg,image/webp,image/gif";\n    else element.value = definition.value || "";\n    if (definition.placeholder) element.placeholder = definition.placeholder;\n    if (definition.required) element.required = true;\n    if (definition.type === "textarea") element.rows = definition.rows || 12;\n    label.appendChild(element); dialog.appendChild(label);\n  });'''
new_editor = '''const openContentEditor = ({ title, description, fields }) => new Promise((resolve) => {\n  const overlay = document.createElement("div"); overlay.className = "content-editor-overlay";\n  const dialog = document.createElement("form"); dialog.className = "content-editor-dialog";\n  dialog.innerHTML = `<div class="content-editor-header"><div><span class="eyebrow">BEARBEITEN</span><h2>${title}</h2><p>${description || "Änderungen prüfen und anschließend speichern."}</p></div><button type="button" class="content-editor-close" aria-label="Schließen">×</button></div>`;\n  fields.forEach((definition) => {\n    const label = document.createElement("label"); label.className = "content-editor-field"; label.textContent = definition.label;\n    const element = definition.type === "textarea" ? document.createElement("textarea") : definition.type === "select" ? document.createElement("select") : document.createElement("input");\n    element.name = definition.name;\n    if (definition.type === "select") {\n      (definition.options || []).forEach(([value, text]) => { const option = document.createElement("option"); option.value = value; option.textContent = text; element.appendChild(option); });\n      element.value = definition.value || definition.options?.[0]?.[0] || "";\n    } else {\n      element.type = definition.type === "file" ? "file" : definition.type || "text";\n      if (definition.type === "file") element.accept = "image/png,image/jpeg,image/webp,image/gif";\n      else element.value = definition.value ?? "";\n      if (definition.min != null) element.min = String(definition.min);\n      if (definition.max != null) element.max = String(definition.max);\n      if (definition.step != null) element.step = String(definition.step);\n    }\n    if (definition.placeholder) element.placeholder = definition.placeholder;\n    if (definition.required) element.required = true;\n    if (definition.type === "textarea") element.rows = definition.rows || 12;\n    label.appendChild(element); dialog.appendChild(label);\n  });'''
app = replace_once(app, old_editor, new_editor, 'content editor controls')

old_home_handlers = '''  async function createHomepageSection(e) {\n    e.preventDefault(); if (!isHeadAdmin(profile?.role)) return showNotice("Nur der Global Admin darf die Startseite gestalten.");\n    const prepared = await preparePrivilegedAction("Startseiten-Beitrag erstellen"); if (prepared.error) return showNotice(prepared.error.message);\n    if (!activeRegionId) return showNotice("Bitte zuerst eine Region auswählen.");\n    const f = new FormData(e.currentTarget); const { error } = await supabase.from("homepage_sections").insert({ title: String(f.get("title") || "").trim(), content: String(f.get("content") || "").trim(), image_url: String(f.get("image_url") || "").trim() || null, frame_style: f.get("frame_style") || "standard", created_by: user.id, updated_by: user.id, sort_order: homepageSections.length, is_visible: true, region_id: activeRegionId });\n    if (error) { showNotice(error.message); return false; } e.currentTarget.reset(); showNotice("Rahmen veröffentlicht."); await loadAll(); return true;\n  }\n  async function editHomepageSection(x) {\n    if (!isHeadAdmin(profile?.role)) return;\n    const values = await openContentEditor({ title: "Startseiten-Beitrag", description: "Du hast hier ausreichend Platz für Text und kannst bei Bedarf ein neues Bild vom Computer oder Handy auswählen.", fields: [{ name: "title", label: "Überschrift", value: x.title, required: true }, { name: "content", label: "Text", type: "textarea", value: x.content, required: true, rows: 16 }, { name: "image", label: "Neues Bild auswählen (optional)", type: "file" }, { name: "image_url", label: "Oder Bild-URL", value: x.image_url || "", placeholder: "https://..." }] });\n    if (!values || values.title.trim().length < 3 || values.content.trim().length < 3) return;\n    const prepared = await preparePrivilegedAction("Startseiten-Beitrag bearbeiten", x.id); if (prepared.error) return showNotice(prepared.error.message);\n    let imageUrl = values.image_url.trim() || null;\n    try { const uploaded = await uploadHomepageImage(values.image); if (uploaded) imageUrl = uploaded; } catch (error) { return showNotice(error.message); }\n    const { error } = await supabase.from("homepage_sections").update({ title: values.title.trim(), content: values.content.trim(), image_url: imageUrl, updated_by: user.id, updated_at: new Date().toISOString() }).eq("id", x.id); if (error) return showNotice(error.message); showNotice("Beitrag gespeichert."); await loadAll();\n  }\n  async function deleteHomepageSection(x) { if (!isHeadAdmin(profile?.role)) return; if (!confirm("Rahmen wirklich löschen?")) return; const prepared = await preparePrivilegedAction("Startseiten-Beitrag löschen", x.id); if (prepared.error) return showNotice(prepared.error.message); const { error } = await supabase.from("homepage_sections").delete().eq("id", x.id); if (error) return showNotice(error.message); await loadAll(); }'''
new_home_handlers = '''  async function createHomepageSection(e) {\n    e.preventDefault();\n    if (!canManageActiveRegion) return showNotice("Du hast in dieser Region keine Rechte für die Startseite.");\n    if (!activeRegionId) return showNotice("Bitte zuerst eine Region auswählen.");\n    const f = new FormData(e.currentTarget);\n    const publicationScope = String(f.get("publication_scope") || "REGION") === "GLOBAL" ? "GLOBAL" : "REGION";\n    if (publicationScope === "GLOBAL" && !isHeadAdmin(profile?.role)) return showNotice("Global veröffentlichen darf nur der Hauptadmin.");\n    const title = String(f.get("title") || "").trim(); const content = String(f.get("content") || "").trim();\n    if (title.length < 3 || content.length < 3) return showNotice("Bitte Überschrift und Text ausfüllen.");\n    const prepared = await preparePrivilegedAction("Startseiten-Beitrag erstellen"); if (prepared.error) return showNotice(prepared.error.message);\n    const payload = {\n      title, content, image_url: String(f.get("image_url") || "").trim() || null,\n      frame_style: String(f.get("frame_style") || "standard"), publication_scope: publicationScope,\n      font_family: String(f.get("font_family") || "modern"), font_size: Number(f.get("font_size") || 18), text_color: String(f.get("text_color") || "#334155"),\n      title_font_family: String(f.get("title_font_family") || "modern"), title_font_size: Number(f.get("title_font_size") || 32), title_color: String(f.get("title_color") || "#0f172a"),\n      created_by: user.id, updated_by: user.id, sort_order: homepageSections.length, is_visible: true, region_id: activeRegionId\n    };\n    const { error } = await supabase.from("homepage_sections").insert(payload);\n    if (error) { showNotice(error.message); return false; }\n    showNotice(publicationScope === "GLOBAL" ? "Beitrag wurde global veröffentlicht." : `Beitrag wurde für ${activeRegion?.name || "die Region"} veröffentlicht.`);\n    await loadAll(); return true;\n  }\n  async function editHomepageSection(x) {\n    const globalEntry = x.publication_scope === "GLOBAL";\n    if (!canManageActiveRegion || (globalEntry && !isHeadAdmin(profile?.role))) return showNotice("Du darfst diesen Startseiten-Beitrag nicht bearbeiten.");\n    const scopeOptions = isHeadAdmin(profile?.role) ? [["REGION", `Nur ${activeRegion?.name || "diese Region"}`], ["GLOBAL", "Global · alle Regionen"]] : [["REGION", `Nur ${activeRegion?.name || "diese Region"}`]];\n    const values = await openContentEditor({ title: "Startseiten-Beitrag bearbeiten", description: "Text, Typografie, Farben, Rahmen und Sichtbarkeit können gemeinsam angepasst werden.", fields: [\n      { name: "publication_scope", label: "Veröffentlichung", type: "select", value: x.publication_scope || "REGION", options: scopeOptions },\n      { name: "frame_style", label: "Rahmenstil", type: "select", value: x.frame_style || "standard", options: [["standard","Standard"],["accent","Akzent"],["soft","Soft"],["dark","Dunkel"]] },\n      { name: "title", label: "Überschrift", value: x.title, required: true },\n      { name: "title_font_family", label: "Schriftart Überschrift", type: "select", value: x.title_font_family || "modern", options: [["modern","Modern"],["serif","Klassisch"],["handwritten","Handschriftlich"]] },\n      { name: "title_font_size", label: "Schriftgröße Überschrift", type: "number", min: 18, max: 56, value: x.title_font_size || 32 },\n      { name: "title_color", label: "Farbe Überschrift", type: "color", value: x.title_color || "#0f172a" },\n      { name: "content", label: "Text", type: "textarea", value: x.content, required: true, rows: 12 },\n      { name: "font_family", label: "Schriftart Text", type: "select", value: x.font_family || "modern", options: [["modern","Modern"],["serif","Klassisch"],["handwritten","Handschriftlich"]] },\n      { name: "font_size", label: "Schriftgröße Text", type: "number", min: 12, max: 36, value: x.font_size || 18 },\n      { name: "text_color", label: "Textfarbe", type: "color", value: x.text_color || "#334155" },\n      { name: "image", label: "Neues Bild auswählen (optional)", type: "file" },\n      { name: "image_url", label: "Oder Bild-URL", value: x.image_url || "", placeholder: "https://..." }\n    ] });\n    if (!values || values.title.trim().length < 3 || values.content.trim().length < 3) return;\n    const nextScope = values.publication_scope === "GLOBAL" ? "GLOBAL" : "REGION";\n    if (nextScope === "GLOBAL" && !isHeadAdmin(profile?.role)) return showNotice("Global veröffentlichen darf nur der Hauptadmin.");\n    const prepared = await preparePrivilegedAction("Startseiten-Beitrag bearbeiten", x.id); if (prepared.error) return showNotice(prepared.error.message);\n    let imageUrl = values.image_url.trim() || null;\n    try { const uploaded = await uploadHomepageImage(values.image); if (uploaded) imageUrl = uploaded; } catch (error) { return showNotice(error.message); }\n    const { error } = await supabase.from("homepage_sections").update({ title: values.title.trim(), content: values.content.trim(), image_url: imageUrl, frame_style: values.frame_style || "standard", publication_scope: nextScope, font_family: values.font_family || "modern", font_size: Number(values.font_size || 18), text_color: values.text_color || "#334155", title_font_family: values.title_font_family || "modern", title_font_size: Number(values.title_font_size || 32), title_color: values.title_color || "#0f172a", region_id: activeRegionId, updated_by: user.id, updated_at: new Date().toISOString() }).eq("id", x.id);\n    if (error) return showNotice(error.message); showNotice("Startseiten-Beitrag gespeichert."); await loadAll();\n  }\n  async function deleteHomepageSection(x) {\n    if (!canManageActiveRegion || (x.publication_scope === "GLOBAL" && !isHeadAdmin(profile?.role))) return showNotice("Du darfst diesen Startseiten-Beitrag nicht löschen.");\n    if (!confirm("Startseiten-Beitrag wirklich löschen?")) return;\n    const prepared = await preparePrivilegedAction("Startseiten-Beitrag löschen", x.id); if (prepared.error) return showNotice(prepared.error.message);\n    const { error } = await supabase.from("homepage_sections").delete().eq("id", x.id); if (error) return showNotice(error.message); await loadAll();\n  }'''
app = replace_once(app, old_home_handlers, new_home_handlers, 'homepage handlers')

old_home_prop = '''<Home profile={profile} user={user} activeRegion={activeRegion} isHeadAdmin={isHeadAdmin} homepageSections={regionFilter(homepageSections)} canEdit={isHeadAdmin(profile?.role)} createHomepageSection={createHomepageSection} editHomepageSection={editHomepageSection} deleteHomepageSection={deleteHomepageSection} uploadHomepageImage={uploadHomepageImage}'''
new_home_prop = '''<Home profile={profile} user={user} activeRegion={activeRegion} isHeadAdmin={isHeadAdmin} homepageSections={visibleHomepageSections} canEdit={canManageActiveRegion} createHomepageSection={createHomepageSection} editHomepageSection={editHomepageSection} deleteHomepageSection={deleteHomepageSection} uploadHomepageImage={uploadHomepageImage}'''
app = replace_once(app, old_home_prop, new_home_prop, 'home props')

old_member_page = '''{page === "members" && <section><div className="page-heading"><div><span className="eyebrow">COMMUNITY</span><h1>Mitglieder · {activeRegion?.name || "Region"}</h1><p>{search.trim() ? "Die Suche findet Mitglieder aus allen drei Regionen." : "Angezeigt werden nur Mitglieder mit dieser Heimatregion."}</p></div><input className="search-input" placeholder="Alle Regionen durchsuchen …" value={search} onChange={(e) => setSearch(e.target.value)}/></div><MemberGrid members={displayedMembers} profile={profile} friendships={friendships} onOpen={openMember} onMessage={openChat}/></section>}'''
new_member_page = '''{page === "members" && <section className="member-directory-native"><div className="page-heading member-directory-heading"><div><span className="eyebrow">COMMUNITY</span><h1>Mitglieder</h1><p>Durchsuche die gesamte Community oder grenze gezielt nach Region und Online-Status ein.</p></div></div><div className="member-directory-controls panel"><label className="member-directory-search"><span>Mitglied suchen</span><input className="search-input" placeholder="Nickname, Vorname oder Nachname …" value={search} onChange={(e) => setSearch(e.target.value)}/></label><label><span>Region</span><select value={memberRegionFilter} onChange={(e) => setMemberRegionFilter(e.target.value)}><option value="ALL">Alle Regionen</option><option value="CURRENT">Aktuelle Region · {activeRegion?.name || "Region"}</option>{regions.map((region) => <option value={region.id} key={region.id}>{region.name}</option>)}</select></label><label className="member-online-filter"><input type="checkbox" checked={membersOnlineOnly} onChange={(e) => setMembersOnlineOnly(e.target.checked)}/><span>Nur Mitglieder, die gerade online sind</span></label><div className="member-directory-quick"><button type="button" className={memberRegionFilter === "ALL" ? "primary-button" : "secondary-button"} onClick={() => setMemberRegionFilter("ALL")}>Alle Regionen</button><button type="button" className={memberRegionFilter === "CURRENT" ? "primary-button" : "secondary-button"} onClick={() => setMemberRegionFilter("CURRENT")}>Meine aktuelle Region</button><strong>{displayedMembers.length} Treffer</strong></div></div><MemberGrid members={displayedMembers} profile={profile} friendships={friendships} onOpen={openMember} onMessage={openChat}/>{!displayedMembers.length && <div className="empty-card">Keine Mitglieder passen zu den gewählten Filtern.</div>}</section>}'''
app = replace_once(app, old_member_page, new_member_page, 'members page')

home_start = app.index('function Home({')
home_end = app.index('\nfunction EngagementPanel(', home_start)
old_home = app[home_start:home_end]
new_home = r'''function Home({ profile, user, activeRegion, isHeadAdmin, homepageSections, canEdit, createHomepageSection, editHomepageSection, deleteHomepageSection, uploadHomepageImage, weeklyPoll, welcomeBadges, groups, featuredGroup, communityRequests, onVote, onCreatePoll, onFeatureGroup, onCreateRequest, onCloseRequest, onOpenGroup }) {
  const emptyDraft = () => ({ publication_scope: "REGION", frame_style: "standard", title: "", content: "", imageUrl: "", title_font_family: "modern", title_font_size: 32, title_color: "#0f172a", font_family: "modern", font_size: 18, text_color: "#334155", status: "" });
  const [draft, setDraft] = useState(emptyDraft);
  const updateDraft = (changes) => setDraft((current) => ({ ...current, ...changes }));
  const fontFamily = (value) => value === "serif" ? "Georgia, 'Times New Roman', serif" : value === "handwritten" ? "'Segoe Print', 'Bradley Hand', cursive" : "Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
  const chooseImage = async (event) => { const file = event.target.files?.[0]; if (!file) return; updateDraft({ status: "Bild wird hochgeladen …" }); try { const imageUrl = await uploadHomepageImage(file); updateDraft({ imageUrl, status: "✓ Bild bereit." }); } catch (error) { updateDraft({ status: `Upload fehlgeschlagen: ${error?.message || "Unbekannter Fehler"}` }); } };
  const save = async (event) => { const saved = await createHomepageSection(event); if (saved) setDraft(emptyDraft()); };
  const titleStyle = (entry) => ({ fontFamily: fontFamily(entry.title_font_family || "modern"), fontSize: `${Number(entry.title_font_size || 32)}px`, color: entry.title_color || "#0f172a" });
  const textStyle = (entry) => ({ fontFamily: fontFamily(entry.font_family || "modern"), fontSize: `${Number(entry.font_size || 18)}px`, color: entry.text_color || "#334155" });
  return <section className="home-page"><div className="page-heading"><div><span className="eyebrow">REGION {activeRegion?.name || "ENNSTAL CONNECT"}</span><h1>Willkommen, {getName(profile)}</h1><p>Entdecke Beiträge, Gruppen und gemeinsame Aktivitäten in {activeRegion?.name || "deiner Region"}.</p></div>{isHeadAdmin(profile?.role) && <div className="head-admin-profile-badge">★ Hauptadmin · Betreiber</div>}</div><EngagementPanel poll={weeklyPoll} badges={welcomeBadges} groups={groups} featuredGroup={featuredGroup} requests={communityRequests} user={user} isHeadAdmin={isHeadAdmin(profile?.role)} onVote={onVote} onCreatePoll={onCreatePoll} onFeatureGroup={onFeatureGroup} onCreateRequest={onCreateRequest} onCloseRequest={onCloseRequest} onOpenGroup={onOpenGroup}/>{canEdit && <details className="homepage-editor-toggle homepage-editor-native"><summary>Startseite gestalten · {activeRegion?.name || "Region"}</summary><div className="homepage-editor-layout"><form onSubmit={save} className="homepage-form homepage-design-form panel"><span className="eyebrow">STARTSEITEN-BEITRAG</span><h2>Inhalt & Design</h2><div className="homepage-editor-grid"><label><span>Veröffentlichung</span><select name="publication_scope" value={draft.publication_scope} onChange={(e) => updateDraft({ publication_scope: e.target.value })}><option value="REGION">Nur {activeRegion?.name || "diese Region"}</option>{isHeadAdmin(profile?.role) && <option value="GLOBAL">Global · alle Regionen</option>}</select></label><label><span>Rahmenstil</span><select name="frame_style" value={draft.frame_style} onChange={(e) => updateDraft({ frame_style: e.target.value })}><option value="standard">Standard</option><option value="accent">Akzent</option><option value="soft">Soft</option><option value="dark">Dunkel</option></select></label></div><label><span>Überschrift</span><input name="title" value={draft.title} onChange={(e) => updateDraft({ title: e.target.value })} placeholder="Überschrift" required/></label><div className="homepage-editor-grid homepage-typography-grid"><label><span>Schriftart Überschrift</span><select name="title_font_family" value={draft.title_font_family} onChange={(e) => updateDraft({ title_font_family: e.target.value })}><option value="modern">Modern</option><option value="serif">Klassisch</option><option value="handwritten">Handschriftlich</option></select></label><label><span>Größe Überschrift</span><input type="number" name="title_font_size" min="18" max="56" value={draft.title_font_size} onChange={(e) => updateDraft({ title_font_size: e.target.value })}/></label><label><span>Farbe Überschrift</span><input type="color" name="title_color" value={draft.title_color} onChange={(e) => updateDraft({ title_color: e.target.value })}/></label></div><label><span>Text</span><textarea name="content" value={draft.content} onChange={(e) => updateDraft({ content: e.target.value })} placeholder="Text für den Startseiten-Beitrag" rows="8" required/></label><div className="homepage-editor-grid homepage-typography-grid"><label><span>Schriftart Text</span><select name="font_family" value={draft.font_family} onChange={(e) => updateDraft({ font_family: e.target.value })}><option value="modern">Modern</option><option value="serif">Klassisch</option><option value="handwritten">Handschriftlich</option></select></label><label><span>Größe Text</span><input type="number" name="font_size" min="12" max="36" value={draft.font_size} onChange={(e) => updateDraft({ font_size: e.target.value })}/></label><label><span>Textfarbe</span><input type="color" name="text_color" value={draft.text_color} onChange={(e) => updateDraft({ text_color: e.target.value })}/></label></div><label><span>Bild-URL (optional)</span><input name="image_url" value={draft.imageUrl} onChange={(e) => updateDraft({ imageUrl: e.target.value })} placeholder="https://…"/></label><label className="homepage-image-picker">Foto hochladen<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={chooseImage}/></label>{draft.status && <p className="homepage-upload-status" aria-live="polite">{draft.status}</p>}<button className="primary-button">Beitrag veröffentlichen</button></form><aside className="homepage-live-preview"><span className="eyebrow">LIVE-VORSCHAU</span><article className={`homepage-frame ${draft.frame_style}`}><>{draft.imageUrl && <img src={draft.imageUrl} alt="Vorschau"/>}</><div><span className="frame-kicker">{draft.publication_scope === "GLOBAL" ? "GLOBAL · ALLE REGIONEN" : activeRegion?.name || "REGION"}</span><h2 style={titleStyle(draft)}>{draft.title || "Deine Überschrift"}</h2><p style={textStyle(draft)}>{draft.content || "Hier siehst du direkt, wie dein Text auf der Startseite wirkt."}</p></div></article></aside></div></details>}{homepageSections.length > 0 && <div className="homepage-sections">{homepageSections.map((x) => <article className={`homepage-frame ${x.frame_style || "standard"}`} key={x.id}>{x.image_url && <img src={x.image_url} alt=""/>}<div><span className="frame-kicker">{x.publication_scope === "GLOBAL" ? "GLOBAL · ALLE REGIONEN" : activeRegion?.name || "ENNSTAL CONNECT"}</span><h2 style={titleStyle(x)}>{x.title}</h2><p style={textStyle(x)}>{x.content}</p>{canEdit && <div className="content-manage-actions"><button onClick={() => editHomepageSection(x)}>✎ Bearbeiten</button><button className="danger-button" onClick={() => deleteHomepageSection(x)}>Löschen</button></div>}</div></article>)}</div>}</section>;
}
'''
app = app[:home_start] + new_home + app[home_end:]

app_path.write_text(app, encoding='utf-8')

main = main_path.read_text(encoding='utf-8')
needle = 'import "./community-native-final.css";'
if 'community-native-editor.css' not in main:
    if main.count(needle) != 1:
        raise SystemExit('main import anchor missing')
    main = main.replace(needle, needle + '\nimport "./community-native-editor.css";', 1)
main_path.write_text(main, encoding='utf-8')

test = test_path.read_text(encoding='utf-8')
old_test = '''  for (const table of ["homepage_sections", "news", "community_events", "community_ads", "forum_posts", "community_requests"]) {\n    assert.match(app, new RegExp(`from\\\\(\\\\"${table}\\\\"\\\\)[\\\\s\\\\S]{0,260}eq\\\\(\\\\"region_id\\\\", activeRegionId\\\\)`));\n  }'''
new_test = '''  for (const table of ["news", "community_events", "community_ads", "forum_posts", "community_requests"]) {\n    assert.match(app, new RegExp(`from\\\\(\\\\"${table}\\\\"\\\\)[\\\\s\\\\S]{0,260}eq\\\\(\\\\"region_id\\\\", activeRegionId\\\\)`));\n  }\n  assert.match(app, /from\\("homepage_sections"\\)[\\s\\S]{0,260}publication_scope\\.eq\\.GLOBAL/);'''
if old_test not in test:
    raise SystemExit('community core audit anchor missing')
test = test.replace(old_test, new_test, 1)
test_path.write_text(test, encoding='utf-8')

css_path.write_text(r'''/* Native member directory and homepage editor. These styles are intentionally scoped. */
.member-directory-native { min-width: 0; }
.member-directory-heading { margin-bottom: 18px; }
.member-directory-controls { display: grid; grid-template-columns: minmax(320px, 1.6fr) minmax(240px, .8fr); gap: 16px 20px; align-items: end; margin-bottom: 22px; padding: 20px; }
.member-directory-controls label { display: grid; gap: 7px; font-weight: 800; color: #183149; }
.member-directory-controls input, .member-directory-controls select { width: 100%; min-height: 48px; border: 1px solid #cbd8e5; border-radius: 13px; background: #fff; padding: 0 14px; font: inherit; }
.member-directory-controls .member-online-filter { display: flex; align-items: center; gap: 10px; min-height: 48px; }
.member-directory-controls .member-online-filter input { width: 20px; min-height: 20px; height: 20px; }
.member-directory-quick { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.member-directory-quick strong { margin-left: auto; padding: 9px 12px; border-radius: 999px; background: #e8f0f6; color: #173149; }
.member-directory-native .member-card[hidden] { display: flex !important; }

.homepage-editor-native { margin: 24px 0; border-radius: 18px; overflow: hidden; }
.homepage-editor-native > summary { cursor: pointer; padding: 16px 18px; font-weight: 900; background: #fff; border: 1px solid #d8e2eb; border-radius: 16px; }
.homepage-editor-layout { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(360px, .85fr); gap: 22px; margin-top: 16px; align-items: start; }
.homepage-design-form { display: grid; gap: 14px; padding: 22px; }
.homepage-design-form > label, .homepage-editor-grid label { display: grid; gap: 7px; font-weight: 800; color: #173149; }
.homepage-design-form input, .homepage-design-form textarea, .homepage-design-form select { width: 100%; border: 1px solid #cbd8e5; border-radius: 13px; background: #fff; padding: 12px 14px; font: inherit; color: #14283a; }
.homepage-design-form textarea { resize: vertical; min-height: 150px; }
.homepage-design-form input[type="color"] { min-height: 48px; padding: 5px; }
.homepage-editor-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.homepage-typography-grid { grid-template-columns: minmax(0, 1.3fr) minmax(110px, .7fr) minmax(110px, .7fr); }
.homepage-image-picker { padding: 12px 14px; border: 1px dashed #a9bccb; border-radius: 13px; background: #f7fafc; }
.homepage-image-picker input { padding: 8px 0 0; border: 0; background: transparent; }
.homepage-live-preview { position: sticky; top: 84px; display: grid; gap: 10px; }
.homepage-live-preview .homepage-frame { margin: 0; min-height: 260px; }
.homepage-frame > div h2 { line-height: 1.16; overflow-wrap: anywhere; }
.homepage-frame > div p { line-height: 1.55; white-space: pre-wrap; overflow-wrap: anywhere; }
.homepage-frame.dark > div h2, .homepage-frame.dark > div p { color: inherit; }
.content-editor-dialog select, .content-editor-dialog input[type="number"], .content-editor-dialog input[type="color"] { width: 100%; min-height: 46px; }
@media (max-width: 1050px) {
  .homepage-editor-layout, .member-directory-controls { grid-template-columns: 1fr; }
  .homepage-live-preview { position: static; }
  .homepage-typography-grid { grid-template-columns: 1fr 1fr; }
  .member-directory-quick { grid-column: 1; }
}
''', encoding='utf-8')

print('native community upgrade prepared')
